use super::*;
use openbindings_internal_schema::{Control as _,preparation::Attempt};
use serde_json::{json,Value};
use std::cell::Cell;
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering::Relaxed};
thread_local!{static EVENTS:Cell<[usize;6]>=const{Cell::new([0;6])};static MARK:Cell<(usize,bool)>=const{Cell::new((0,false))};}
pub(super) fn event(i:usize){EVENTS.with(|s|{let mut x=s.get();x[i]+=1;s.set(x);});}
pub(super) fn snapshot(r:&Run){EVENTS.with(|s|{let mut x=s.get();x[3]=r.memo.keys().filter(|k|r.plan.fields(k.schema).is_leaf()).count();x[4]=r.memo.keys().filter(|k|r.plan.fields(k.schema).is_leaf()&&k.instance!=r.root_instance).count();x[5]=r.root_instance;s.set(x);});}
pub(super) fn mark(done:bool){MARK.with(|s|{let(n,_)=s.get();s.set((n+usize::from(!done),done));});}
fn reset(){EVENTS.with(|s|s.set([0;6]));}
fn stats()->[usize;6]{EVENTS.with(Cell::get)}
fn environment(schema:&str)->SchemaEnvironment{
 let proof=Document::parse(r#"{"openbindings":"0.2.0","operations":{"op":{"input":{"$ref":"https://root-review.invalid/schema"}}}}"#).unwrap().validate().unwrap().conformant().unwrap();let s=proof.operation("op").unwrap().input().unwrap();let ext=ExternalSchemas::new(vec![ExternalSchema{uri:"https://root-review.invalid/schema".into(),document:JsonValue::parse(schema).unwrap()}]).unwrap();s.environment(&ext,&PreparationLimits::default(),&AtomicBool::new(false)).unwrap()
}
fn plan(schema:&str)->Plan{let e=environment(schema);let p=PreparationLimits::default();Attempt::run(p.max_sdk_work_units,p.max_sdk_reservation_bytes,&||false,|a|Plan::new(e,Limits::default(),p,a)).unwrap().unwrap()}
fn repeated(count:usize,leaf:Value)->String{json!({"$defs":{"A":leaf},"allOf":(0..count).map(|_|json!({"$ref":"#/$defs/A"})).collect::<Vec<_>>()}).to_string()}
fn label(o:&ValueOutcome)->String{match o{ValueOutcome::Satisfies=>"S".into(),ValueOutcome::Fails{..}=>"F".into(),ValueOutcome::Undefined{..}=>"U".into(),ValueOutcome::NoVerdict{detail}=>format!("N:{:?}",detail.reason)}}
fn eval(p:&Plan,v:&JsonValue,d:Detail)->ValueOutcome{reset();p.evaluate(v,d,&AtomicBool::new(false))}
#[test]fn multiplicity_exact_entry_counts_and_no_one_use_chain_mark(){
 for n in[0,1,2,64,5000]{let schema=if n==0{r#"{"type":"integer"}"#.into()}else{repeated(n,json!({"type":"integer"}))};let p=plan(&schema);let targets=p.queries.values().filter_map(|q|q.as_ref().as_ref().ok()).filter(|q|p.fields(q.node).is_leaf()).map(|q|q.node).collect::<Vec<_>>();let shared=p.fields.values().filter(|f|f.is_shared_leaf()).count();assert_eq!(shared,usize::from(n>=2));
 if n>=2{assert!(p.queries.values().enumerate().any(|(i,a)|p.queries.values().skip(i+1).any(|b|Arc::ptr_eq(a,b))),"shared query result was not exercised");}
 for(text,want)in[("1","S"),("\"x\"","F")]{for d in[Detail::Outcome,Detail::Explain]{let o=eval(&p,&JsonValue::parse(text).unwrap(),d);assert_eq!(label(&o),want);let s=stats();if n>=2{let passes=if d==Detail::Explain&&want=="F"{2}else{1};assert_eq!(s[0],passes);assert_eq!(s[1],(n-1)*passes);assert_eq!(s[2],passes);assert_eq!(s[3],1);assert_eq!(s[4],0);}else{assert_eq!(s[0]+s[1]+s[3],0);}println!("ROOT_REUSE {}",json!({"n":n,"value":text,"detail":format!("{d:?}"),"stats":s,"outcome":o}));}}
 println!("TARGETS {}",json!({"n":n,"incoming_leaf_edges":targets.len(),"shared":shared}));}
 let chain=r##"{"$defs":{"A":{"$ref":"#/$defs/B"},"B":{"type":"integer"}},"$ref":"#/$defs/A"}"##;let p=plan(chain);assert!(p.queries.len()>1);assert_eq!(p.fields.values().filter(|f|f.is_shared_leaf()).count(),0);assert_eq!(label(&eval(&p,&JsonValue::parse("1").unwrap(),Detail::Outcome)),"S");assert_eq!(stats()[0]+stats()[1]+stats()[3],0);
 let indirect=r##"{"$defs":{"A":{"allOf":[{"type":"integer"}]}},"allOf":[{"$ref":"#/$defs/A"},{"$ref":"#/$defs/A"}]}"##;let p=plan(indirect);assert_eq!(p.fields.values().filter(|f|f.is_shared_leaf()).count(),0);assert_eq!(label(&eval(&p,&JsonValue::parse("1").unwrap(),Detail::Outcome)),"S");assert_eq!(stats()[0]+stats()[1]+stats()[3],0);
}
#[test]fn root_subtree_and_equal_child_name_ids_do_not_expand_leaf_retention(){
 let p=plan(&repeated(2,json!({"type":"integer"})));let owner=JsonValue::parse(r#"{"padding":0,"v":7}"#).unwrap();let v=owner.get("v").unwrap().to_owned();let id=backend::ref_id(v.view());assert_ne!(id,0);drop(owner);assert_eq!(label(&eval(&p,&v,Detail::Explain)),"S");assert_eq!(stats()[5],id);assert_eq!(stats()[3],1);
 let array=r##"{"$defs":{"A":{"type":"integer"}},"items":{"$ref":"#/$defs/A"},"propertyNames":{"$ref":"#/$defs/A"}}"##;let p=plan(array);assert_eq!(p.fields.values().filter(|f|f.is_shared_leaf()).count(),1);for bad in[false,true]{let mut vals=vec![json!(1);50001];if bad{vals[50000]=json!("bad");}let v=JsonValue::parse(serde_json::to_string(&vals).unwrap()).unwrap();assert_eq!(label(&eval(&p,&v,Detail::Outcome)),if bad{"F"}else{"S"});assert_eq!(stats()[0]+stats()[1]+stats()[3]+stats()[4],0);}
 let object=r##"{"$defs":{"A":true},"additionalProperties":{"$ref":"#/$defs/A"},"propertyNames":{"$ref":"#/$defs/A"}}"##;let p=plan(object);let v=JsonValue::parse(r#"{"same":"same","other":"same"}"#).unwrap();assert_eq!(label(&eval(&p,&v,Detail::Explain)),"S");assert_eq!(stats()[0]+stats()[1]+stats()[3]+stats()[4],0);
}
struct Stop{calls:AtomicUsize,at:usize}impl WorkControl for Stop{fn is_cancelled(&self)->bool{self.calls.fetch_add(1,Relaxed)>=self.at}}
#[test]fn all_actual_hit_miss_stops_and_budget_boundaries_retry_cleanly(){
 for text in["1","\"bad\""]{let mut p=plan(&repeated(8,json!({"type":"integer"})));let v=JsonValue::parse(text).unwrap();let c=Stop{calls:AtomicUsize::new(0),at:usize::MAX};let ordinary=p.evaluate(&v,Detail::Outcome,&c);let verdict=c.calls.load(Relaxed);
 for d in[Detail::Outcome,Detail::Explain]{let c=Stop{calls:AtomicUsize::new(0),at:usize::MAX};let expected=p.evaluate(&v,d,&c);let total=c.calls.load(Relaxed);for at in 0..total{let stopped=p.evaluate(&v,d,&Stop{calls:AtomicUsize::new(0),at});if d==Detail::Explain&&label(&ordinary)=="F"&&at>=verdict{assert!(matches!(stopped,ValueOutcome::Fails{problems,problems_complete:false,..}if problems.is_empty()));}else{assert!(matches!(stopped,ValueOutcome::NoVerdict{detail}if detail.reason==NoVerdictReason::Cancelled));}assert_eq!(serde_json::to_value(p.evaluate(&v,d,&AtomicBool::new(false))).unwrap(),serde_json::to_value(&expected).unwrap());}println!("ROOT_STOPS {}",json!({"text":text,"detail":format!("{d:?}"),"count":total}));}
 for allocation in[false,true]{let mut low=0;let mut high=if allocation{48<<20}else{100000};while low<high{let middle=(low+high)/2;if allocation{p.limits.program_bytes=middle}else{p.limits.evaluation_steps=Some(middle)}let ok=label(&p.evaluate(&v,Detail::Outcome,&AtomicBool::new(false)))==label(&ordinary);if ok{high=middle}else{low=middle+1;}}assert!(low>0);if allocation{p.limits.program_bytes=low}else{p.limits.evaluation_steps=Some(low)}assert_eq!(label(&p.evaluate(&v,Detail::Outcome,&AtomicBool::new(false))),label(&ordinary));if allocation{p.limits.program_bytes=low-1}else{p.limits.evaluation_steps=Some(low-1)}assert!(matches!(p.evaluate(&v,Detail::Outcome,&AtomicBool::new(false)),ValueOutcome::NoVerdict{detail}if detail.reason==NoVerdictReason::LimitExceeded));println!("ROOT_BOUNDARY {}",json!({"text":text,"allocation":allocation,"minimum":low}));p.limits=Limits::default();}
 }
}
#[test]fn marking_pass_checks_each_query_and_final_publication(){
 let e=environment(&repeated(8,json!({"type":"integer"})));let limits=PreparationLimits::default();MARK.with(|s|s.set((0,false)));let p=Attempt::run(limits.max_sdk_work_units,limits.max_sdk_reservation_bytes,&||false,|a|Plan::new(e.clone(),Limits::default(),limits,a)).unwrap().unwrap();let n=p.queries.len();assert_eq!(MARK.with(Cell::get),(n,true));
 for stop in 1..=n+1{MARK.with(|s|s.set((0,false)));let c=||{let(k,done)=MARK.with(Cell::get);if stop==n+1{done}else{k>=stop}};let result=Attempt::run(limits.max_sdk_work_units,limits.max_sdk_reservation_bytes,&c,|a|Plan::new(e.clone(),Limits::default(),limits,a));assert!(result.is_err());MARK.with(|s|s.set((0,false)));assert!(Attempt::run(limits.max_sdk_work_units,limits.max_sdk_reservation_bytes,&||false,|a|Plan::new(e.clone(),Limits::default(),limits,a)).unwrap().is_ok());}
 println!("MARK_STOPS {}",n+1);
}
fn run<'a>(p:&'a Plan,v:&JsonValue,c:&'a dyn WorkControl)->Run<'a>{Run{plan:p,root_instance:backend::ref_id(v.view()),record_witnesses:false,graph:Graph::new(48<<20,None,64,c),atoms:Vec::new(),values:values::Values::default(),effects:HashMap::new(),active:storage::Entries::default(),alias_path:storage::Entries::default(),empty_context:Arc::new(Vec::new()),opaque_cycles:HashSet::new(),pending_cycles:HashSet::new(),cuts:HashSet::new(),provisional:HashSet::new(),memo:HashMap::new(),facts:HashMap::new(),pending_facts:HashMap::new(),supports:HashMap::new(),support_memo_count:0,patterns:storage::Entries::default()}}
#[test]fn exact_context_distinguishes_entries_and_cut_dependent_or_error_state_is_not_published(){
 for (leaf,expected)in[(json!({"type":"integer"}),"S"),(json!({"pattern":"["}),"U"),(json!({"pattern":"(a)\\1"}),"N:UnsupportedCapability"),(json!({"pattern":"a{65535}"}),"N:LimitExceeded")]{let p=plan(&repeated(2,leaf));let target=*p.fields.iter().find(|(_,f)|f.is_shared_leaf()).unwrap().0;let v=JsonValue::parse(if expected=="S"{"1"}else{"\"a\""}).unwrap();let c=AtomicBool::new(false);let mut r=run(&p,&v,&c);
 let context:Context=Arc::new(vec![("x".into(),Some(target))]);let other:Context=Arc::new(vec![("x".into(),None)]);let a=execution::review_root_leaf(&mut r,target,v.view(),context.clone());if expected=="N:LimitExceeded"{assert!(a.is_err());assert!(r.memo.is_empty());continue;}let a=a.unwrap();assert_eq!(r.memo.len(),1);execution::review_root_leaf(&mut r,target,v.view(),Arc::new((*context).clone())).unwrap();assert_eq!(r.memo.len(),1);execution::review_root_leaf(&mut r,target,v.view(),other).unwrap();assert_eq!(r.memo.len(),2);
 if a.valid>=2{r.memo.clear();for x in r.graph.support(a.valid).unwrap(){r.cuts.insert(x);}execution::review_root_leaf(&mut r,target,v.view(),context).unwrap();assert!(r.memo.is_empty());}
 let out=eval(&p,&v,Detail::Outcome);assert_eq!(label(&out),expected);println!("ROOT_EFFECT {}",json!({"expected":expected,"outcome":out}));}
}
#[test]fn memo_hit_keeps_enclosing_attempt_failure_and_cancellation(){
 let p=plan(&repeated(2,json!({"type":"integer"})));let target=*p.fields.iter().find(|(_,f)|f.is_shared_leaf()).unwrap().0;let v=JsonValue::parse("1").unwrap();
 for failure in["work","allocation","cancel"]{let c=AtomicBool::new(false);let outcome=Attempt::run(100000,100000,&c,|a|{let mut r=run(&p,&v,&c);r.graph=Graph::with_preparation(48<<20,None,64,&c,Some(a));let context=r.empty_context.clone();execution::review_root_leaf(&mut r,target,v.view(),context.clone()).unwrap();assert_eq!(r.memo.len(),1);
 match failure{"work"=>{assert!(a.charge_work(usize::MAX).is_err());},"allocation"=>{assert!(a.charge_allocation(usize::MAX).is_err());},_=>c.store(true,Relaxed)}
 let e=execution::review_root_leaf(&mut r,target,v.view(),context).err().unwrap();assert_eq!(e.code,match failure{"work"=>"preparation-sdk-work-units","allocation"=>"preparation-sdk-reservation-bytes",_=>"caller-cancelled"});assert_eq!(r.memo.len(),1);});assert!(outcome.is_err());assert_eq!(label(&eval(&p,&v,Detail::Outcome)),"S");}
}
#[test]fn selected_custom_meta_uses_same_root_leaf_route_and_shared_attempt(){
 let proof=Document::parse(r#"{"openbindings":"0.2.0","operations":{"op":{"input":{"$ref":"https://root-review.invalid/custom"}}}}"#).unwrap().validate().unwrap().conformant().unwrap();let schema=proof.operation("op").unwrap().input().unwrap();let resources=ExternalSchemas::new(vec![
 ExternalSchema{uri:"https://root-review.invalid/custom".into(),document:JsonValue::parse(r#"{"$schema":"https://root-review.invalid/meta","type":"integer"}"#).unwrap()},
 ExternalSchema{uri:"https://root-review.invalid/meta".into(),document:JsonValue::parse(r##"{"$schema":"https://json-schema.org/draft/2020-12/schema","$vocabulary":{"https://json-schema.org/draft/2020-12/vocab/core":true,"https://json-schema.org/draft/2020-12/vocab/validation":true},"$defs":{"A":{"type":"object"}},"allOf":[{"$ref":"#/$defs/A"},{"$ref":"#/$defs/A"}]}"##).unwrap()}]).unwrap();
 reset();let prepared=schema.prepare(&crate::DefaultEvaluator::default(),&resources,&PreparationLimits::default()).unwrap();let s=stats();assert!(s[0]>0&&s[1]>0,"actual meta route missing {s:?}");assert_eq!(label(&prepared.evaluate(&JsonValue::parse("1").unwrap())),"S");assert_eq!(label(&prepared.evaluate(&JsonValue::parse("\"bad\"").unwrap())),"F");println!("META_REUSE {}",json!(s));
}
